// Normalise a raw Notion client row into flat fields plus a Slack-safe channel
// name. Property names are matched case-insensitively so the workflow survives
// small differences between client databases.

// Everyone listed here is invited to every new client channel. Slack member IDs
// look like U01ABCDEF — in Slack: click a profile, then ⋯ → Copy member ID.
// Leave the array empty and the invite step is skipped.
const TEAM_USER_IDS = [];

// Channel names become <prefix><client>, e.g. client-acme-corp.
const CHANNEL_PREFIX = 'client-';
const CURRENCY = 'USD';

const plain = (arr) => (arr || []).map((t) => t.plain_text).join('').trim();

const pick = (props, ...names) => {
  const keys = Object.keys(props);
  for (const name of names) {
    const key = keys.find((k) => k.toLowerCase() === name.toLowerCase());
    if (key) return props[key];
  }
  return undefined;
};

const readText = (p) => (p ? plain(p.title) || plain(p.rich_text) : '');
const readChoice = (p) => p?.select?.name || p?.status?.name || '';
const readMulti = (p) => (p?.multi_select || []).map((o) => o.name).join(', ');
const readPeople = (p) =>
  (p?.people || [])
    .map((u) => u.name || u.person?.email)
    .filter(Boolean)
    .join(', ');
const readEmails = (p) =>
  (p?.people || [])
    .map((u) => u.person?.email)
    .filter(Boolean);
const readEmail = (p) => p?.email || readText(p);
const readUrl = (p) => p?.url || '';
const readDate = (p) => p?.date?.start || '';
const readNumber = (p) => (typeof p?.number === 'number' ? p.number : null);

const prettyDate = (iso) => {
  if (!iso) return '';
  // Notion sends dates as plain 'YYYY-MM-DD'. Parsing those as UTC and then
  // formatting in local time shifts the day backwards west of UTC, so pin them.
  const dateOnly = !iso.includes('T');
  const d = new Date(dateOnly ? `${iso}T00:00:00Z` : iso);
  if (Number.isNaN(d.getTime())) return iso;
  const opts = dateOnly
    ? { year: 'numeric', month: 'short', day: 'numeric', timeZone: 'UTC' }
    : { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' };
  return d.toLocaleDateString('en-US', opts);
};

const money = (n) => {
  if (n === null) return '';
  try {
    return n.toLocaleString('en-US', {
      style: 'currency',
      currency: CURRENCY,
      maximumFractionDigits: 0,
    });
  } catch (e) {
    return String(n);
  }
};

// Slack channel rules: lowercase only, 80 characters max, and nothing outside
// letters, digits, hyphens and underscores — otherwise conversations.create
// rejects the name with invalid_name_specials.
const toChannelName = (value) => {
  const slug = (value || '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return `${CHANNEL_PREFIX}${slug || 'unnamed'}`.slice(0, 80).replace(/-+$/, '');
};

const results = [];

for (const item of $input.all()) {
  const page = item.json;
  const props = page.properties || {};

  // The client-name column can be called anything, so find it by type first.
  const titleKey = Object.keys(props).find((k) => props[k]?.type === 'title');
  const clientName = titleKey ? plain(props[titleKey].title) : '';

  const ownerProp = pick(props, 'Owner', 'Account Manager', 'CSM', 'Assigned to', 'Assignee');
  const industryProp = pick(props, 'Industry', 'Sector', 'Vertical');

  const industry = readChoice(industryProp) || readMulti(industryProp) || readText(industryProp);
  const plan = readChoice(pick(props, 'Plan', 'Tier', 'Package', 'Product'));
  const stage = readChoice(pick(props, 'Status', 'Stage', 'Onboarding Status'));
  const owner = readPeople(ownerProp) || readText(ownerProp);
  const ownerEmails = readEmails(ownerProp);
  const startDate = readDate(
    pick(props, 'Start Date', 'Kickoff', 'Kickoff Date', 'Onboarding Date', 'Go Live'),
  );
  const contractValue = readNumber(
    pick(props, 'Contract Value', 'Value', 'ARR', 'MRR', 'Deal Size'),
  );
  const contact = readEmail(pick(props, 'Primary Contact', 'Contact', 'Contact Email', 'Email'));
  const website = readUrl(pick(props, 'Website', 'URL', 'Domain')) ||
    readText(pick(props, 'Website', 'Domain'));
  const region = readChoice(pick(props, 'Region', 'Market', 'Timezone'));
  const notes = readText(pick(props, 'Notes', 'Description', 'Scope', 'Summary'));

  results.push({
    json: {
      pageId: page.id,
      clientName,
      channelName: toChannelName(clientName),
      industry,
      plan,
      stage,
      owner,
      ownerEmails,
      startDate,
      startDatePretty: prettyDate(startDate),
      contractValue,
      contractValuePretty: money(contractValue),
      contact,
      website,
      region,
      notes,
      notionUrl: page.url || '',
      createdBy: page.created_by?.name || '',
      createdTime: page.created_time || '',
      inviteUserIds: TEAM_USER_IDS,
    },
  });
}

return results;

// The channel exists by now, so build both Slack messages in one place: the
// welcome post that goes inside the new channel, and the announcement that goes
// to the team channel. Every Slack node downstream reads this node's output via
// $('Prepare Slack Payloads').item.json, so nothing gets derived twice.

const ONBOARDING_STEPS = [
  'Share the kickoff deck and agenda',
  'Collect access, credentials and brand assets',
  'Book the kickoff call with the client',
  'Link the project plan in this channel',
];

const clientItems = $('Format Client').all();
// Fallback lookup for the rare case where n8n loses the paired-item trail.
const byChannelName = new Map(clientItems.map((it) => [it.json.channelName, it.json]));

const results = [];

$input.all().forEach((item, index) => {
  // n8n unwraps the conversations.create response; older builds keep `channel`.
  const created = item.json.channel || item.json;
  const channelId = created.id || '';
  const channelName = created.name || '';

  let client;
  try {
    client = $('Format Client').itemMatching(index).json;
  } catch (e) {
    client = byChannelName.get(channelName) || clientItems[index]?.json || {};
  }

  const fields = [];
  const addField = (label, value) => {
    if (value) fields.push({ type: 'mrkdwn', text: `*${label}*\n${value}` });
  };

  addField('Plan', client.plan);
  addField('Industry', client.industry);
  addField('Owner', client.owner);
  addField('Kickoff', client.startDatePretty);
  addField('Contract value', client.contractValuePretty);
  addField('Region', client.region);
  addField('Primary contact', client.contact);
  addField('Website', client.website);

  const channelLink = channelId ? `<#${channelId}>` : `#${channelName}`;
  const channelUrl = channelId ? `https://slack.com/app_redirect?channel=${channelId}` : '';
  const name = client.clientName || channelName || 'New client';

  // ── Welcome message, posted inside the new channel ────────────────────────
  const welcomeBlocks = [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: `:handshake: Welcome aboard, ${name}!`.slice(0, 150),
        emoji: true,
      },
    },
  ];

  // Slack allows at most 10 fields in a single section.
  if (fields.length) {
    welcomeBlocks.push({ type: 'section', fields: fields.slice(0, 10) });
  }

  if (client.notes) {
    welcomeBlocks.push({
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: client.notes.length > 2800 ? `${client.notes.slice(0, 2800)}…` : client.notes,
      },
    });
  }

  welcomeBlocks.push({ type: 'divider' });
  welcomeBlocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*First steps*\n${ONBOARDING_STEPS.map((s) => `• ${s}`).join('\n')}`,
    },
  });

  if (client.notionUrl) {
    welcomeBlocks.push({
      type: 'actions',
      elements: [
        {
          type: 'button',
          text: { type: 'plain_text', text: 'Open client record', emoji: true },
          url: client.notionUrl,
          style: 'primary',
        },
      ],
    });
  }

  welcomeBlocks.push({
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text: `Channel created by n8n${client.createdBy ? ` for ${client.createdBy}` : ''}`,
      },
    ],
  });

  // ── Announcement, posted to the shared team channel ───────────────────────
  const announceBlocks = [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: `:tada: New client: ${name}`.slice(0, 150),
        emoji: true,
      },
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `Onboarding has started in ${channelLink}${
          client.owner ? `, led by *${client.owner}*` : ''
        }.`,
      },
    },
  ];

  const announceFields = fields.filter((f) =>
    ['*Plan*', '*Industry*', '*Kickoff*', '*Contract value*'].some((label) =>
      f.text.startsWith(label),
    ),
  );

  if (announceFields.length) {
    announceBlocks.push({ type: 'section', fields: announceFields });
  }

  const buttons = [];
  if (channelUrl) {
    buttons.push({
      type: 'button',
      text: { type: 'plain_text', text: `Open #${channelName}`.slice(0, 75), emoji: true },
      url: channelUrl,
      style: 'primary',
    });
  }
  if (client.notionUrl) {
    buttons.push({
      type: 'button',
      text: { type: 'plain_text', text: 'Open client record', emoji: true },
      url: client.notionUrl,
    });
  }
  if (buttons.length) {
    announceBlocks.push({ type: 'actions', elements: buttons });
  }

  const welcomeText = `Welcome aboard, ${name}!`;
  const announceText = `New client: ${name} — onboarding in #${channelName}`;

  results.push({
    json: {
      ...client,
      channelId,
      channelName,
      channelUrl,
      inviteUserIds: client.inviteUserIds || [],
      welcomeText,
      announceText,
      slackWelcome: { blocks: welcomeBlocks, text: welcomeText },
      slackAnnouncement: { blocks: announceBlocks, text: announceText },
    },
  });
});

return results;
